Translate("esES", "alba-fairmoon", {
	title = "Alba Fairmoon",
	subtitle = "Investigadora de la tierra envenenada",
	found = "La posada de la Colina del Centinela",
	hint = [=[Hable con la elfa de la noche que estudia la enfermedad del suelo de Páramos de Poniente.]=],
	allegiance = "Darnassus",
	aliases = { "Alba" },
	sections = {
		{
			title = "Resumen",
			text = [=[Alba Fairmoon es una {link:night-elves}elfa de la noche{/link} de {link:darnassus}Darnassus{/link} que ha venido a {link:westfall}Páramos de Poniente{/link} para averiguar por qué se muere su tierra. Empezó por el agua, analizando los pozos de las granjas, y los encontró llenos de metales venenosos. Siguió el veneno por las minas y la cantera, y por fin hasta {link:moonbrook}Arroyo de la Luna{/link}, donde halló señales de grandes obras bajo tierra.]=],
		},
		{
			title = "Importancia",
			text = [=[Alba teme que, si no se detiene el veneno, los cultivos no crecerán en {link:westfall}Páramos de Poniente{/link} durante décadas, y {link:stormwind-city}Ventormenta{/link} sufrirá hambruna.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Analizó los pozos de {link:the-jansen-stead}La Finca de Jansen{/link} y de {link:the-molsen-farm}La Granja de Molsen{/link}.
• Siguió el rastro del veneno hasta una forja oculta en las {link:the-deadmines}Minas de la Muerte{/link}.]=],
		},
	},
	chapters = {
		{
			title = "La forja de abajo",
			hint = "Siga el veneno de los pozos hasta su origen.",
			text = [=[Con explosivos fabricados en {link:stormwind-city}Ventormenta{/link}, la forja de las {link:the-deadmines}Minas de la Muerte{/link} fue destruida. Alba esperó en las colinas detrás de {link:moonbrook}Arroyo de la Luna{/link} para verlo hecho. Después habló con pesar de un reino que parecía valorar más sus guerras que el sustento de su propia gente.]=],
		},
	},
	mentions = {
		{ text = "Analizar los pozos" },
		{ text = "Branquias de {link:murlocs}múrloc{/link}" },
		{ text = "El estado de las minas" },
		{ text = "Espionaje en {link:moonbrook}Arroyo de la Luna{/link}" },
		{ text = "Consulta explosiva" },
		{
			text = [=[Destrucción en las {link:the-deadmines}Minas de la Muerte{/link}]=],
		},
	},
	bonds = {
		{ id = "gryan-stoutmantle", name = "Gryan Stoutmantle", note = "defiende la tierra que ella estudia" },
	},
})

Translate("esES", "ozwin-ironsprocket", {
	title = "Ozwin Ironsprocket",
	subtitle = "Manitas de Gnomeregan",
	found = "El establo de la Finca de Saldean",
	hint = [=[Busque en el establo de la Finca de Saldean a un gnomo escondido.]=],
	allegiance = "Exiliado de Gnomeregan",
	aliases = { "Ozwin" },
	sections = {
		{
			title = "Resumen",
			text = [=[Ozwin Ironsprocket es un {link:gnomes}gnomo{/link} que vino desde {link:ironforge}Forjaz{/link} al enterarse de que los {link:harvest-golems}gólems de cosecha{/link} andaban descontrolados en {link:westfall}Páramos de Poniente{/link}. Pretendía recalibrarlos. Las máquinas resultaron mucho más agresivas de lo que sus cálculos preveían, y lo persiguieron hasta el establo de la {link:saldeans-farm}Finca de Saldean{/link}, donde se esconde desde entonces.]=],
		},
		{
			title = "Importancia",
			text = [=[Ozwin es el único en {link:westfall}Páramos de Poniente{/link} que intenta comprender a los {link:harvest-golems}gólems de cosecha{/link} en lugar de limitarse a destruirlos.]=],
