		{ text = "Cosechar a los cosechadores" },
	},
	bonds = {
		{ id = "farmer-saldean", name = "Granjero Saldean", note = "lo cobija en su establo" },
	},
})

Translate("esES", "harvest-golems", {
	title = "Gólems de cosecha",
	aliases = { "gólems de cosecha", "Gólem de cosecha", "gólem de cosecha", "Vigías de cosecha", "Vigía de cosecha", "máquinas de cosecha" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los gólems de cosecha son grandes máquinas de hierro construidas para trabajar los campos de {link:westfall}Páramos de Poniente{/link}. Se hicieron para segar, sembrar y vigilar los cultivos. Ahora recorren las granjas abandonadas sin amo y ahuyentan a cualquiera que se acerque, como si los propios granjeros fueran plagas que hubiera que limpiar de las hileras.]=],
		},
		{
			title = "Tipos",
			text = [=[• Los {b}gólems de cosecha oxidados{/b} y los {b}gólems de cosecha{/b} son los más pequeños y débiles.
• Los {b}Vigías de cosecha{/b} montan guardia sobre los campos, como indica su nombre.
• Los {b}Segadores de cosecha{/b} son los más grandes y peligrosos. Recorren los campos quemados de {link:the-dead-acre}El Campo Funesto{/link}.
• {b}El Segador de enemigos 4000{/b} es una máquina única, mucho más fuerte que las demás, que recorre los campos de las llanuras occidentales.]=],
		},
		{
			title = "En estos días",
			text = [=[Ningún granjero puede decir con certeza cómo se estropearon las máquinas. Muchos en {link:westfall}Páramos de Poniente{/link} culpan a la {link:defias-brotherhood}Hermandad Defias{/link}, cuyos aliados goblins construyen y dirigen gólems en las profundidades de las {link:the-deadmines}Minas de la Muerte{/link}. El {link:gnomes}gnomo{/link} {link:ozwin-ironsprocket}Ozwin Ironsprocket{/link} ha estudiado sus piezas y ha aprendido a anularlas, aunque solo por un momento. El fantasma del {link:westfall-lighthouse}Faro de Poniente{/link} alimenta su llama con aceite extraído de sus articulaciones. El granjero {link:farmer-saldean}Saldean{/link} simplemente quiere que desaparezcan.]=],
		},
	},
})
